<script lang="ts">let{label,checked=$bindable(false),disabled=false}:{label:string;checked?:boolean;disabled?:boolean}=$props();</script>
<label class="ds-switch"><span>{label}</span><input type="checkbox" role="switch" bind:checked {disabled}/><span class="track" aria-hidden="true"><i></i></span></label>
<style>.ds-switch{display:inline-flex;align-items:center;gap:.75rem;cursor:pointer;color:var(--ds-text);font:.875rem var(--ds-font)}input{position:absolute;opacity:0;width:1px}.track{width:2.5rem;height:1.375rem;padding:3px;border-radius:999px;background:var(--ds-border);flex:none}.track i{display:block;width:.875rem;height:.875rem;border-radius:50%;background:white;transition:transform 140ms}input:checked+.track{background:var(--ds-primary)}input:checked+.track i{transform:translateX(1.125rem)}input:focus-visible+.track{outline:3px solid var(--color-primary);outline-offset:2px}</style>